function PARTITIONS(n, max_part = n):
    if n == 0: return [ () ]
    result <- []
    for k from min(n, max_part) down to 1:
        for rest in PARTITIONS(n - k, k):
            append (k,) ++ rest to result
    return result

function P(n):            # the partition number p(n)
    return length(PARTITIONS(n))

