function PERM_PARTITION(perm):
    n <- length(perm); seen <- [false]*n; lengths <- []
    for i from 0 to n-1:
        if seen[i]: continue
        length <- 0; j <- i
        while not seen[j]:
            seen[j] <- true; j <- perm[j]; length <- length + 1
        append length to lengths
    return sort_descending(lengths)

function HOOK_DIMENSION(part, n):
    rows <- list(part)
    cols[c] <- #{ r in rows : r > c }   for c in 0..rows[0]-1
    prod <- 1
    for i, row_len in enumerate(rows):
        for j from 0 to row_len-1:
            arm <- row_len - j - 1       # cells to the right
            leg <- cols[j] - i - 1       # cells below
            prod <- prod * (arm + leg + 1)
    return n! / prod
